import * as Core from './core.js';
import {openDb,allDocs,saveDoc,newDoc,newPage,encodeDoc,decodeDoc} from './storage.js';
import * as Drive from './drive.js';
const $=selector=>document.querySelector(selector), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let docs=[],current=null,view='all',folder='',selected=new Set(),urls=[],working=false,installPrompt=null,stream=null,dialogCleanup=null;
const doc=()=>docs.find(d=>d.id===current);
const url=blob=>{const u=URL.createObjectURL(blob);urls.push(u);return u;};
const button=(label,fn,primary=false)=>{const b=document.createElement('button');b.className=primary?'primary':'secondary';b.textContent=label;b.onclick=fn;return b;};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function run(label,fn){if(working)return;working=true;$('#busy-text').textContent=label;$('#busy').hidden=false;try{await fn();await refresh();}catch(error){console.error(error.name);toast(error.message||'تعذر إكمال العملية، حاول مرة ثانية.');}finally{working=false;$('#busy').hidden=true;}}
async function refresh(){docs=await allDocs();render();}
async function persist(d,touch=true){const saved=await saveDoc(d,touch);docs=docs.map(x=>x.id===saved.id?saved:x);if(!docs.some(x=>x.id===saved.id))docs.push(saved);return saved;}
function closeModal(){if(dialogCleanup){dialogCleanup();dialogCleanup=null;}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}$('#modal').close();$('#modal-body').replaceChildren();$('#modal-actions').replaceChildren();}
function modal(title,html,actions=[]){closeModal();$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal-actions').replaceChildren(...actions);$('#modal').showModal();}
function download(blob,name){const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
const safeName=name=>name.replace(/[\\/:*?"<>|]/g,'_').slice(0,120);
function goHome(){current=null;selected.clear();render();}
function render(){
  for(const u of urls)URL.revokeObjectURL(u);urls=[];
  $('#home').hidden=!!current;$('#editor').hidden=!current;
  $('#count').textContent=docs.filter(d=>!d.trashed).length;
  document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
  if(current){if(!doc()){goHome();return;}renderEditor();return;}
  $('#heading').innerHTML=view==='trash'?'سلة المحذوفات<span>.</span>':view==='favorite'?'قريبين لقلبك<span>.</span>':'مستنداتك، ببساطة<span>.</span>';
  $('#crumb').textContent=view==='trash'?'المحذوفات':view==='favorite'?'المفضلة':'المستندات';
  const search=$('#search').value.toLowerCase(),sort=$('#sort').value;
  const shown=docs.filter(d=>(view==='trash'?d.trashed:!d.trashed)&&(view!=='favorite'||d.favorite)&&(!folder||d.folder===folder)&&(d.name.toLowerCase().includes(search)||d.folder.toLowerCase().includes(search)));
  shown.sort(sort==='name'?(a,b)=>a.name.localeCompare(b.name,'ar'):(a,b)=>b[sort]-a[sort]);
  $('#library-count').textContent=`${shown.length} مستند`;
  const folders=[...new Set(docs.filter(d=>!d.trashed&&d.folder).map(d=>d.folder))];
  $('#folders').replaceChildren(...['',...folders].map(f=>{const b=button(f||'كل المجلدات',()=>{folder=f;render();});b.className=`chip ${f===folder?'active':''}`;return b;}));
  $('#documents').innerHTML=shown.map(d=>`<article class="doc-card"><div class="doc-cover" data-open="${esc(d.id)}" role="button" tabindex="0" aria-label="فتح ${esc(d.name)}">${d.pages[0]?`<img src="${url(d.pages[0].blob)}" alt="معاينة أول صفحة" loading="lazy">`:'<div class="blank-doc">▤</div>'}</div><div class="doc-info"><h3>${esc(d.name)}</h3><p>${d.pages.length} صفحات · ${new Date(d.updated).toLocaleDateString('ar')} ${d.folder?'· '+esc(d.folder):''}</p><div class="doc-actions"><button data-fav="${esc(d.id)}" class="${d.favorite?'favorite':''}" aria-label="تبديل المفضلة">${d.favorite?'★':'☆'}</button><button data-open="${esc(d.id)}">فتح ←</button><button data-trash="${esc(d.id)}">${d.trashed?'استعادة':'للسلة'}</button></div></div></article>`).join('');
  $('#empty').hidden=shown.length>0;
}
function renderEditor(){
  const d=doc();selected=new Set([...selected].filter(s=>d.pages.some(p=>p.id===s)));
  $('#doc-title').textContent=d.name;$('#doc-meta').textContent=`${d.pages.length} صفحات${d.folder?' · '+d.folder:''}${d.trashed?' · موجود في سلة المحذوفات':''}`;
  $('#compose').disabled=selected.size!==2;$('#split').disabled=selected.size!==1;$('#extract').disabled=selected.size===0;
  $('#selection-label').textContent=selected.size?`تم تحديد ${selected.size} صفحة`:'حدد صفحة لتعديلها، أو صفحتين لدمجهما في صفحة واحدة.';
  $('#pages').innerHTML=d.pages.map((p,i)=>`<article class="page-card ${selected.has(p.id)?'selected':''}"><div class="page-head"><label><input type="checkbox" data-select="${esc(p.id)}" ${selected.has(p.id)?'checked':''}>صفحة ${i+1}</label><div><button class="icon-btn" data-move="${esc(p.id)}" data-dir="-1" aria-label="نقل الصفحة للأعلى" ${i===0?'disabled':''}>↑</button><button class="icon-btn" data-move="${esc(p.id)}" data-dir="1" aria-label="نقل الصفحة للأسفل" ${i===d.pages.length-1?'disabled':''}>↓</button></div></div><img src="${url(p.blob)}" data-zoom="${esc(p.id)}" alt="صفحة ${i+1}" loading="lazy"><div class="page-tools"><button data-crop="${esc(p.id)}">قصّ</button><button data-enhance="${esc(p.id)}">تحسين</button><button data-rotate="${esc(p.id)}">↻ تدوير</button><button data-annotate="${esc(p.id)}">توقيع / قلم</button><button data-original="${esc(p.id)}">الأصل</button><button data-remove="${esc(p.id)}">حذف</button></div></article>`).join('');
}
async function importImages(files,target=current){
  if(!files.length)return;
  await run('عم نجهّز الصفحات…',async()=>{
    let d=docs.find(x=>x.id===target)||newDoc();
    if(d.pages.length+files.length>80)throw Error('حد المستند الحالي 80 صفحة. افتح مستنداً جديداً.');
    const pages=[];for(let i=0;i<files.length;i++){const normalized=await Core.normalize(files[i]);pages.push(newPage(normalized.blob,normalized.width,normalized.height));$('#busy-text').textContent=`إضافة الصفحة ${i+1}/${files.length}…`;}
    d=await persist({...d,pages:[...d.pages,...pages]});current=d.id;selected.clear();toast('تم حفظ الصفحات على جهازك');
  });
}
async function addCanvasPages(canvases,d=doc()){const pages=[];for(const c of canvases)pages.push(newPage(await Core.toBlob(c),c.width,c.height));if(d.pages.length+pages.length>80)throw Error('قسّم المستند قبل إضافة صفحات جديدة.');await persist({...d,pages:[...d.pages,...pages]});}
async function replacePage(pageId,canvas){const d=doc(),old=d.pages.find(p=>p.id===pageId);const updated={...old,blob:await Core.toBlob(canvas),width:canvas.width,height:canvas.height};await persist({...d,pages:d.pages.map(p=>p.id===pageId?updated:p)});}
function editName(){const d=doc();modal('اسم المستند ومجلده',`<div class="form-row"><label>اسم المستند<input id="name-input" value="${esc(d.name)}" maxlength="150"></label></div><div class="form-row"><label>المجلد<input id="folder-input" value="${esc(d.folder)}" maxlength="100" placeholder="مثلاً: أوراق شخصية"></label></div>`,[button('حفظ',()=>{const name=$('#name-input').value.trim(),f=$('#folder-input').value.trim();if(!name)return toast('اكتب اسم المستند');closeModal();run('حفظ…',()=>persist({...d,name,folder:f}));},true)]);}
function composeDialog(){
  const d=doc(),pages=d.pages.filter(p=>selected.has(p.id));let result=null,generation=0;
  modal('صفحتان، في صفحة واحدة',`<div class="form-row"><label>ترتيب الصفحتين<select id="layout"><option value="vertical">فوق بعض</option><option value="horizontal">بجانب بعض</option></select></label><label>المقاس<select id="paper-size"><option value="a4">A4</option><option value="letter">Letter</option></select></label></div><div class="form-row"><label>اتجاه الصفحة<select id="orientation"><option value="portrait">عمودي</option><option value="landscape">أفقي</option></select></label><label>الهوامش<input id="margin" type="range" min="0" max="100" value="35"></label></div><div class="form-row"><label><input id="swap" type="checkbox"> عكس ترتيب الصفحتين</label></div><div id="composition-preview" class="preview-grid"></div><p class="hint">النتيجة صفحة واحدة فعلية. تُضاف للمستند، والصفحتان الأصليتان بيضلّوا محفوظين.</p>`,[button('إضافة الصفحة',()=>{if(!result)return;const c=result;closeModal();run('حفظ الصفحة الجديدة…',async()=>{await addCanvasPages([c],d);toast('انضافت الصفحة الجديدة، والأصل محفوظ');});},true)]);
  async function preview(){const version=++generation;result=null;try{const c=await Core.composePages(pages.map(p=>p.blob),{vertical:$('#layout').value==='vertical',landscape:$('#orientation').value==='landscape',size:$('#paper-size').value,margin:Number($('#margin').value),swap:$('#swap').checked});if(version!==generation)return;result=c;$('#composition-preview')?.replaceChildren(c);}catch(e){toast(e.message);}}
  $('#modal-body').onchange=preview;$('#margin').oninput=preview;preview();dialogCleanup=()=>{generation++;$('#modal-body').onchange=null;};
}
function splitDialog(){
  const d=doc(),page=d.pages.find(p=>selected.has(p.id));let results=[],generation=0;
  modal('تقسيم محتوى الصفحة',`<div class="form-row"><label>اتجاه الفصل<select id="split-axis"><option value="vertical">يمين ويسار — مثل كتاب مفتوح</option><option value="horizontal">أعلى وأسفل</option></select></label><label>عدد الصفحات الناتجة<select id="split-count"><option value="2">صفحتان</option><option value="3">3 صفحات</option><option value="4">4 صفحات</option></select></label></div><div id="cut-sliders"></div><div class="form-row"><label><input id="reverse" type="checkbox" checked> ترتيب من اليمين لليسار / عكس النتائج</label></div><div id="split-preview" class="preview-grid"></div><p class="hint">حرّك مكان الفصل، وراجع كل جزء قبل الحفظ. الصفحة الأصلية رح تضل موجودة.</p>`,[button('إضافة الصفحات',()=>{if(!results.length)return;const output=results;closeModal();run('حفظ الصفحات…',async()=>{await addCanvasPages(output,d);toast('تم تقسيم الصفحة مع الاحتفاظ بالأصل');});},true)]);
  function sliders(){const count=Number($('#split-count').value);$('#cut-sliders').innerHTML=Array.from({length:count-1},(_,i)=>`<label>خط الفصل ${i+1}<input class="cut" type="range" min="5" max="95" value="${100*(i+1)/count}"></label>`).join('');}
  async function preview(){const version=++generation;results=[];try{const fractions=[...document.querySelectorAll('.cut')].map(el=>Number(el.value)/100);const output=await Core.splitPage(page.blob,$('#split-axis').value==='vertical',fractions,$('#reverse').checked);if(version!==generation)return;results=output;$('#split-preview').replaceChildren(...output.map((c,i)=>{const wrap=document.createElement('div');wrap.className='part';const text=document.createElement('small');text.textContent=`صفحة ${i+1}`;wrap.append(c,text);return wrap;}));}catch(e){toast(e.message);}}
  sliders();$('#split-count').onchange=()=>{sliders();preview();};$('#split-axis').onchange=()=>{if($('#split-axis').value==='horizontal')$('#reverse').checked=false;preview();};$('#reverse').onchange=preview;$('#cut-sliders').oninput=preview;preview();dialogCleanup=()=>generation++;
}
function enhanceDialog(pageId){
  const page=doc().pages.find(p=>p.id===pageId);let result,generation=0;
  modal('تحسين وضوح الصفحة',`<div class="form-row"><label>الفلتر<select id="filter"><option value="original">بدون فلتر إضافي</option><option value="gray">رمادي</option><option value="bw">أبيض وأسود</option></select></label></div><div class="form-row"><label>الإضاءة<input id="brightness" type="range" min="-80" max="80" value="0"></label><label>التباين<input id="contrast" type="range" min="-80" max="80" value="0"></label></div><div id="enhance-preview" class="preview-grid"></div><p class="hint">الصورة الأصلية محفوظة. فيك ترجع إلها بزر «الأصل».</p>`,[button('تطبيق',()=>{if(!result)return;const c=result;closeModal();run('تحسين الصفحة…',()=>replacePage(pageId,c));},true)]);
  let timer;
  async function preview(){const version=++generation;const options={filter:$('#filter').value,brightness:Number($('#brightness').value),contrast:Number($('#contrast').value)};const c=await Core.enhance(page.blob,options);if(version!==generation)return;result=c;$('#enhance-preview')?.replaceChildren(c);}
  $('#filter').onchange=()=>preview().catch(e=>toast(e.message));for(const key of ['brightness','contrast'])$('#'+key).oninput=()=>{result=null;generation++;clearTimeout(timer);timer=setTimeout(()=>preview().catch(e=>toast(e.message)),120);};preview().catch(e=>toast(e.message));dialogCleanup=()=>{generation++;clearTimeout(timer);};
}
async function cropDialog(pageId){
  const page=doc().pages.find(p=>p.id===pageId),img=await Core.image(page.blob),scale=Math.min(1,900/Math.max(img.width,img.height)),canvas=Core.makeCanvas(img.width*scale,img.height*scale),ctx=canvas.getContext('2d');let points=[{x:.04,y:.04},{x:.96,y:.04},{x:.96,y:.96},{x:.04,y:.96}],drag=-1;
  modal('قصّ وتصحيح منظور الورقة','<p class="hint">اسحب الزوايا الأربع إلى حدود الورقة، ثم طبّق القصّ. التحسين يدوي في هذه النسخة.</p><div class="crop-wrap" id="crop-area"></div>',[button('تطبيق القصّ',()=>{const corners=points.map(p=>({...p}));closeModal();run('تصحيح المنظور…',async()=>{const c=await Core.perspectiveCrop(page.blob,corners);await replacePage(pageId,c);});},true)]);
  $('#crop-area').append(canvas);
  function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);ctx.fillStyle='#163b3260';ctx.beginPath();ctx.rect(0,0,canvas.width,canvas.height);ctx.moveTo(points[0].x*canvas.width,points[0].y*canvas.height);for(let i=3;i>=0;i--)ctx.lineTo(points[i].x*canvas.width,points[i].y*canvas.height);ctx.fill('evenodd');ctx.strokeStyle='#73dcad';ctx.lineWidth=3;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x*canvas.width,p.y*canvas.height):ctx.moveTo(p.x*canvas.width,p.y*canvas.height));ctx.closePath();ctx.stroke();points.forEach(p=>{ctx.beginPath();ctx.arc(p.x*canvas.width,p.y*canvas.height,10,0,2*Math.PI);ctx.fillStyle='white';ctx.fill();ctx.stroke();});}
  function position(event){const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(event.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(event.clientY-r.top)/r.height))};}
  canvas.onpointerdown=event=>{const p=position(event);drag=points.reduce((best,q,i)=>Math.hypot(p.x-q.x,p.y-q.y)<Math.hypot(p.x-points[best].x,p.y-points[best].y)?i:best,0);canvas.setPointerCapture(event.pointerId);points[drag]=p;draw();};canvas.onpointermove=event=>{if(drag<0)return;points[drag]=position(event);draw();};canvas.onpointerup=()=>{drag=-1;};canvas.onpointercancel=()=>{drag=-1;};draw();dialogCleanup=()=>img.close();
}
async function annotateDialog(pageId){
  const page=doc().pages.find(p=>p.id===pageId),img=await Core.image(page.blob),canvas=Core.makeCanvas(img.width,img.height),ctx=canvas.getContext('2d');ctx.drawImage(img,0,0);img.close();let down=false,last=null,history=[];
  modal('توقيع، قلم أو طمس دائم',`<div class="form-row"><label>الأداة<select id="pen-mode"><option value="pen">قلم / توقيع بالإصبع</option><option value="highlight">تمييز</option><option value="redact">طمس دائم أسود</option></select></label><label>لون القلم<input id="pen-color" type="color" value="#163f35"></label><label>حجم القلم<input id="pen-size" type="range" min="2" max="45" value="8"></label></div><div class="actions-wrap"><button class="secondary" id="undo-ink">تراجع</button><button class="secondary" id="add-text">إضافة نص / تاريخ</button></div><div id="ink-canvas"></div><p class="hint">التوقيع مرئي وليس توقيعاً رقمياً موثّقاً. الطمس يُحذف من صورة التصدير فعلياً، لكن الأصل يبقى في التطبيق والنسخ الاحتياطية؛ لا تشارك النسخة الاحتياطية لإخفاء معلومات حساسة.</p>`,[button('حفظ التعديلات',()=>{closeModal();run('حفظ التعديلات…',()=>replacePage(pageId,canvas));},true)]);
  canvas.className='edit-canvas';$('#ink-canvas').append(canvas);
  function pos(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};}
  function checkpoint(){history.push(ctx.getImageData(0,0,canvas.width,canvas.height));if(history.length>3)history.shift();}
  canvas.onpointerdown=e=>{checkpoint();down=true;last=pos(e);canvas.setPointerCapture(e.pointerId);};
  canvas.onpointermove=e=>{if(!down)return;const p=pos(e),mode=$('#pen-mode').value;ctx.strokeStyle=mode==='redact'?'#000':mode==='highlight'?'#ead059':$('#pen-color').value;ctx.lineWidth=mode==='redact'?Math.max(20,Number($('#pen-size').value)*4):mode==='highlight'?Number($('#pen-size').value)*3:Number($('#pen-size').value);ctx.lineCap=mode==='redact'?'square':'round';ctx.globalAlpha=mode==='highlight'?.25:1;ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.globalAlpha=1;last=p;};canvas.onpointerup=()=>{down=false;};canvas.onpointercancel=()=>{down=false;};
  $('#undo-ink').onclick=()=>{if(history.length)ctx.putImageData(history.pop(),0,0);};$('#add-text').onclick=()=>{const text=prompt('النص أو التاريخ الذي تريد إضافته:',new Date().toLocaleDateString('ar'));if(!text)return;checkpoint();ctx.fillStyle=$('#pen-color').value;ctx.font=`${Math.max(24,canvas.width*.035)}px Tahoma, Arial`;ctx.textAlign='right';ctx.fillText(text,canvas.width*.95,canvas.height*.93,canvas.width*.9);};
}
function exportDialog(){
  const d=doc();if(!d.pages.length)return toast('أضف صفحة قبل التصدير');let generated=null;
  modal('تصدير المستند',`<div class="form-row"><label>حجم الصفحة<select id="export-size"><option value="a4">A4</option><option value="letter">Letter</option><option value="original">نسبة الصورة الأصلية</option></select></label><label>الاتجاه<select id="export-orientation"><option value="portrait">عمودي</option><option value="landscape">أفقي</option></select></label></div><div class="form-row"><label>الجودة<select id="quality"><option value="0.92">عالية</option><option value="0.75">متوسطة — ملف أصغر</option><option value="0.55">اقتصادية</option></select></label><label><input id="selected-export" type="checkbox" ${selected.size?'':'disabled'}> الصفحات المحددة فقط</label></div><div class="actions-wrap"><button class="secondary" id="jpg-export">تنزيل JPG</button><button class="secondary" id="png-export">تنزيل PNG</button><button class="secondary" id="print-doc">طباعة</button></div><p class="hint">لا نضيف علامة مائية. PDF يحافظ على ترتيب الصفحات وتعديلاتك. تصدير الصور المتعددة قد يطلب إذن تنزيلات متعددة من Chrome.</p><div id="share-ready"></div>`,[button('إنشاء وتنزيل PDF',()=>{const options={size:$('#export-size').value,landscape:$('#export-orientation').value==='landscape',quality:Number($('#quality').value)},pages=exportPages();run('إنشاء PDF…',async()=>{generated=await Core.makePdf(pages,options);download(generated,safeName(d.name)+'.pdf');const share=button('مشاركة الملف الجاهز',()=>shareFile(generated,safeName(d.name)+'.pdf'),true);$('#share-ready')?.replaceChildren(share);toast('تم إنشاء PDF');});},true)]);
  function exportPages(){return $('#selected-export').checked?d.pages.filter(p=>selected.has(p.id)):d.pages;}
  for(const kind of ['jpg','png'])$('#'+kind+'-export').onclick=()=>{const pages=exportPages();run('تصدير الصور…',async()=>{for(let i=0;i<pages.length;i++){const image=await Core.image(pages[i].blob),c=Core.makeCanvas(image.width,image.height);c.getContext('2d').drawImage(image,0,0);image.close();download(await Core.toBlob(c,kind==='png'?'image/png':'image/jpeg'),`${safeName(d.name)}-${i+1}.${kind}`);}});};
  $('#print-doc').onclick=()=>{const images=exportPages().map(p=>URL.createObjectURL(p.blob));const win=window.open('','_blank');if(!win)return toast('اسمح بفتح نافذة للطباعة');win.document.write(`<!doctype html><html><head><title>${esc(d.name)}</title><style>@page{size:A4;margin:10mm}img{display:block;width:100%;height:270mm;object-fit:contain;break-after:page}img:last-child{break-after:auto}</style></head><body>${images.map(u=>`<img src="${u}" alt="صفحة">`).join('')}</body></html>`);win.document.close();win.onload=()=>win.print();};
}
function shareFile(blob,name){const file=new File([blob],name,{type:blob.type});if(navigator.canShare?.({files:[file]}))navigator.share({files:[file],title:doc()?.name||'ورقة'}).catch(e=>{if(e.name!=='AbortError')toast('تعذرت المشاركة، نزّل الملف بدلاً منها.');});else download(blob,name);}
async function openCamera(){
  if(!navigator.mediaDevices?.getUserMedia){$('#capture-file').click();return;}
  modal('مسح بالكاميرا','<video id="camera-video" autoplay playsinline muted></video><p class="hint">ضع الورقة ضمن الصورة بإضاءة واضحة. بعد التصوير تستطيع قصّها وتصحيح المنظور.</p>',[button('التقاط الصفحة',()=>{const video=$('#camera-video');if(!video?.videoWidth)return toast('انتظر تشغيل الكاميرا');const c=Core.makeCanvas(video.videoWidth,video.videoHeight);c.getContext('2d').drawImage(video,0,0);const target=current;closeModal();Core.toBlob(c).then(b=>importImages([b],target)).catch(e=>toast(e.message));},true),button('كاميرا الهاتف',()=>{closeModal();$('#capture-file').click();})]);
  try{const acquired=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920}},audio:false});if(!$('#modal').open||!$('#camera-video')){acquired.getTracks().forEach(t=>t.stop());return;}stream=acquired;$('#camera-video').srcObject=stream;}catch(e){closeModal();toast('الكاميرا غير متاحة. جرّب كاميرا الهاتف أو استيراد الصور.');$('#capture-file').click();}
}
function settings(){
  const clientId=localStorage.getItem('waraqa-oauth-client')||'',last=localStorage.getItem('waraqa-last-sync');
  modal('الإعدادات والمزامنة',`<section class="settings-block"><h3>Google Drive — اختياري</h3><p>يحفظ نسخة من مستنداتك في مساحة بيانات التطبيق المخفية. لا يقرأ ملفات Drive الأخرى. الربط يحتاج إعداد OAuth مرة واحدة.</p><label>معرّف OAuth لتطبيق ويب<input id="oauth-client" dir="ltr" value="${esc(clientId)}" placeholder="…apps.googleusercontent.com"></label><div class="actions-wrap"><button id="prepare-google" class="secondary">تجهيز تسجيل Google</button><button id="google-connect" class="primary" disabled>ربط الحساب</button><button id="drive-sync" class="secondary" ${Drive.connected()?'':'disabled'}>مزامنة الآن</button><button id="drive-disconnect" class="secondary">فصل الجلسة</button></div><p id="drive-status">${last?'آخر مزامنة: '+new Date(last).toLocaleString('ar'):'ما تمت مزامنة بعد.'}</p><p>المزامنة يدوية أثناء فتح التطبيق. النسخ المتعارضة تُحفظ كمستندات منفصلة. النسخ السحابية القديمة تبقى محفوظة وتستهلك مساحة من حسابك.</p><details><summary>كيف أجهّز حساب غوغل؟</summary><p>في Google Cloud: فعّل Drive API، أنشئ OAuth Client من نوع Web، وأضف أصل هذا الموقع ضمن Authorized JavaScript origins: <b dir="ltr">${esc(location.origin)}</b>. أضف حسابك لمستخدمي الاختبار ثم الصق Client ID هون. لا تضع Client Secret.</p></details></section><section class="settings-block"><h3>نسخة احتياطية محلية</h3><p>نزّل نسخة قابلة للاستعادة، خصوصاً قبل حذف بيانات المتصفح. النسخة تشمل الصور الأصلية حتى لو طمست معلومات في صورة التصدير.</p><div class="actions-wrap"><button id="backup-export" class="secondary">تنزيل نسخة احتياطية</button><button id="backup-import" class="secondary">استعادة نسخة</button><button id="persist-storage" class="secondary">طلب حفظ دائم</button><button id="merge-documents" class="secondary">دمج مستندات</button></div></section><section><h3>تثبيت على Android</h3><p>من قائمة Chrome اختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية». بعد أول فتح تقدر تستخدم الميزات المحلية بدون إنترنت. قد تحتاج صفحة الاستضافة الخاصة إعادة تسجيل الدخول؛ جرّب وضع الطيران على هاتفك قبل الاعتماد عليه.</p><p>النسخة الحالية لا تتضمن استخراج النص OCR أو PDF بكلمة مرور.</p></section>`,[button('تم',closeModal,true)]);
  $('#prepare-google').onclick=async()=>{const value=$('#oauth-client').value.trim();localStorage.setItem('waraqa-oauth-client',value);try{await Drive.googleScript();$('#google-connect').disabled=false;$('#drive-status').textContent='جاهز. اضغط ربط الحساب لفتح نافذة Google.';}catch(e){toast(e.message);}};
  $('#google-connect').onclick=()=>{const value=$('#oauth-client').value.trim();localStorage.setItem('waraqa-oauth-client',value);Drive.authorize(value).then(()=>{toast('تم ربط Drive. اختر مزامنة الآن.');$('#drive-sync').disabled=false;$('#drive-status').textContent='الحساب مربوط لهذه الجلسة فقط.';}).catch(e=>toast(e.message));};
  $('#drive-sync').onclick=()=>run('بدء المزامنة…',async()=>{const result=await Drive.syncDrive(text=>$('#busy-text').textContent=text);toast(`تمت المزامنة: ${result.changed} نسخة`);if($('#drive-status'))$('#drive-status').textContent=`آخر مزامنة ناجحة: ${new Date().toLocaleString('ar')}`;});
  $('#drive-disconnect').onclick=()=>{Drive.disconnect();$('#drive-sync').disabled=true;toast('تم فصل الجلسة. الملفات المحلية والسحابية باقية.');};
  $('#backup-export').onclick=()=>run('تجهيز النسخة الاحتياطية…',async()=>{const records=[];for(const d of docs)records.push(await encodeDoc(d));download(new Blob([JSON.stringify({app:'waraqa',schema:1,documents:records})],{type:'application/json'}),`waraqa-${new Date().toISOString().slice(0,10)}.waraqa`);toast('النسخة جاهزة');});
  $('#backup-import').onclick=()=>{closeModal();$('#backup-file').click();};
  $('#persist-storage').onclick=async()=>{const granted=await navigator.storage?.persist?.();toast(granted?'المتصفح وافق على الحفظ الدائم':'المتصفح لم يمنح الحفظ الدائم. احتفظ بنسخة احتياطية.');};
  $('#merge-documents').onclick=mergeDocuments;
}
function mergeDocuments(){const records=docs.filter(d=>!d.trashed);modal('جمع مستندات في مستند واحد',`<p class="hint">هاي العملية تجمع الصفحات بالتتابع. لإنشاء صفحة واحدة من صفحتين، افتح مستنداً وحدد الصفحتين.</p>${records.map(d=>`<div class="form-row"><label><input class="merge-check" type="checkbox" value="${esc(d.id)}"> ${esc(d.name)} — ${d.pages.length} صفحات</label></div>`).join('')}`,[button('إنشاء المستند',()=>{const ids=[...document.querySelectorAll('.merge-check:checked')].map(e=>e.value);if(ids.length<2)return toast('حدد مستندين على الأقل');const pages=ids.flatMap(x=>docs.find(d=>d.id===x).pages).map(p=>({...p,id:Core.id()}));if(pages.length>80)return toast('حد المستند 80 صفحة');closeModal();run('دمج المستندات…',async()=>{const d=await persist({...newDoc('مستند مدمج'),pages});current=d.id;});},true)]);}
function extractPages(){const d=doc(),pages=d.pages.filter(p=>selected.has(p.id)).map(p=>({...p,id:Core.id()}));run('استخراج الصفحات…',async()=>{const result=await persist({...newDoc(d.name+' — صفحات مستخرجة'),pages,folder:d.folder});current=result.id;selected.clear();toast('تم إنشاء مستند جديد، الأصل محفوظ');});}
async function restoreBackup(file){if(file.size>80*1024*1024)return toast('النسخة أكبر من الحد المدعوم: 80 ميغابايت');run('استعادة النسخة…',async()=>{const backup=JSON.parse(await file.text());if(backup.app!=='waraqa'||backup.schema!==1||!Array.isArray(backup.documents)||backup.documents.length>500)throw Error('ملف النسخة غير مدعوم');const decoded=[];for(const value of backup.documents)decoded.push(await decodeDoc(value));for(let d of decoded){const existing=docs.find(x=>x.id===d.id);if(existing?.rev===d.rev)continue;if(existing)d={...d,id:Core.id(),name:d.name+' (نسخة مستعادة)',rev:Core.id(),ancestors:[]};await persist(d,false);}toast('تمت الاستعادة بدون استبدال مستنداتك');});}
function events(){
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;folder='';goHome();});
  for(const name of ['import','empty-import','add-pages','add-tile'])$('#'+name).onclick=()=>$('#files').click();
  $('#add-tile').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#files').click();}};
  for(const name of ['scan','add-camera','mobile-scan'])$('#'+name).onclick=()=>openCamera().catch(e=>toast(e.message));
  $('#files').onchange=e=>{const files=[...e.target.files];e.target.value='';importImages(files);};$('#capture-file').onchange=e=>{const files=[...e.target.files];e.target.value='';importImages(files);};$('#backup-file').onchange=e=>{const file=e.target.files[0];e.target.value='';if(file)restoreBackup(file);};
  $('#new-doc').onclick=()=>run('إنشاء مستند…',async()=>{const d=await persist(newDoc('مستند جديد'));current=d.id;selected.clear();});
  $('#search').oninput=render;$('#sort').onchange=render;$('#back').onclick=goHome;$('#rename').onclick=editName;$('#compose').onclick=composeDialog;$('#split').onclick=splitDialog;$('#extract').onclick=extractPages;$('#export').onclick=exportDialog;
  $('#select-all').onclick=()=>{selected=selected.size===doc().pages.length?new Set():new Set(doc().pages.map(p=>p.id));render();};
  for(const name of ['settings-open','mobile-settings'])$('#'+name).onclick=settings;
  $('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('waraqa-dark',String(document.body.classList.contains('dark')));};
  $('#modal-close').onclick=closeModal;$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
  $('#documents').onclick=e=>{const target=e.target.closest('button,[data-open]');if(!target)return;if(target.dataset.open){current=target.dataset.open;selected.clear();render();}else if(target.dataset.fav){const d=docs.find(x=>x.id===target.dataset.fav);run('حفظ…',()=>persist({...d,favorite:!d.favorite}));}else if(target.dataset.trash){const d=docs.find(x=>x.id===target.dataset.trash);run('حفظ…',()=>persist({...d,trashed:!d.trashed}));}};
  $('#documents').onkeydown=e=>{if(e.key==='Enter'||e.key===' ')e.target.closest('[data-open]')?.click();};
  $('#pages').onchange=e=>{if(e.target.dataset.select){const p=e.target.dataset.select;if(e.target.checked)selected.add(p);else selected.delete(p);render();}};
  $('#pages').onclick=e=>{const t=e.target.closest('button,img');if(!t)return;const d=doc();if(t.dataset.zoom){const p=d.pages.find(x=>x.id===t.dataset.zoom);modal('معاينة الصفحة',`<img class="zoom-image" src="${url(p.blob)}" alt="الصفحة بالحجم الكامل">`,[button('إغلاق',closeModal)]);}
    else if(t.dataset.crop)cropDialog(t.dataset.crop).catch(e=>toast(e.message));else if(t.dataset.enhance)enhanceDialog(t.dataset.enhance);else if(t.dataset.annotate)annotateDialog(t.dataset.annotate).catch(e=>toast(e.message));
    else if(t.dataset.rotate)run('تدوير…',async()=>replacePage(t.dataset.rotate,await Core.rotate(d.pages.find(p=>p.id===t.dataset.rotate).blob)));
    else if(t.dataset.move)run('ترتيب الصفحات…',async()=>{const pages=[...d.pages],i=pages.findIndex(p=>p.id===t.dataset.move),j=i+Number(t.dataset.dir);if(j<0||j>=pages.length)return;[pages[i],pages[j]]=[pages[j],pages[i]];await persist({...d,pages});});
    else if(t.dataset.original){if(!confirm('العودة للصورة الأصلية تحذف تعديلات هذه الصفحة. متابعة؟'))return;run('استعادة الأصل…',async()=>{const page=d.pages.find(p=>p.id===t.dataset.original),image=await Core.image(page.original),updated={...page,blob:page.original,width:image.width,height:image.height};image.close();await persist({...d,pages:d.pages.map(p=>p.id===page.id?updated:p)});});}
    else if(t.dataset.remove){const pageId=t.dataset.remove;modal('حذف الصفحة من المستند؟','<p>يمكنك إلغاء العملية الآن. بعد الحفظ تحتاج نسخة احتياطية سابقة لاستعادتها.</p>',[button('إلغاء',closeModal),button('حذف الصفحة',()=>{closeModal();run('حذف الصفحة…',()=>persist({...d,pages:d.pages.filter(p=>p.id!==pageId)}));},true)]);}
  };
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false;});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true;}};
  window.addEventListener('online',network);window.addEventListener('offline',network);
}
function network(){$('#offline').textContent=navigator.onLine?'محلي وآمن':'بدون إنترنت';}
async function init(){try{await openDb();document.body.classList.toggle('dark',localStorage.getItem('waraqa-dark')==='true');events();network();await refresh();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('تعذر تفعيل العمل بدون إنترنت في هذا المتصفح.'));}catch(e){toast(e.message);$('#empty').innerHTML='<h3>تعذر فتح التخزين المحلي</h3><p>جرّب Chrome بدون التصفح الخفي، واسمح بتخزين بيانات الموقع.</p>';}}
init();
